// Pre-index by barcode string for O(1) instantaneous lookups
const BARCODE_INDEX = new Map();
for (const p of NATIONAL_PRODUCTS) {
    if (p.barcode) {
        BARCODE_INDEX.set(p.barcode.trim(), p);
    }
}

/**
 * Instant local lookup by exact or trimmed barcode.
 * Returns product object with suggested name, category, and price or null.
 */
export function findInNationalCatalog(barcode) {
    if (!barcode) return null;
    const clean = String(barcode).trim();
    if (!clean) return null;
    return BARCODE_INDEX.get(clean) || null;
}
